export function SearchField({ value, onChange }: Props) {
  const ref = useRef<HTMLInputElement>(null)
  const [focused, setFocused] = useState(false)

  useEffect(() => {
    return deferVisualClass(ref.current, 'is-focused', focused)
  }, [focused])

  return (
